const uiMap=new Map(uiRows.map(r=>[r[0],r]));
function deviceLanguage(){const locales=typeof navigator!=='undefined'?(navigator.languages?.length?navigator.languages:[navigator.language||'en']):['az'];for(const locale of locales){const code=String(locale).toLowerCase().split(/[-_]/)[0];if(languageOptions.some(x=>x[0]===code))return code}return 'en'}
function lang(){try{const l=JSON.parse(localStorage.getItem('basira-language'));return languageOptions.some(x=>x[0]===l)?l:deviceLanguage()}catch{return deviceLanguage()}}
function tr(s){const i=languageOptions.findIndex(x=>x[0]===lang());if(i<=0)return s;const row=uiMap.get(String(s).trim());if(row)return row[i];let out=String(s);const parts=out.split(/( · | → | ← |: |\n)/);if(parts.length>1)out=parts.map(p=>uiMap.get(p.trim())?.[i]||p).join('');const units={tr:['ayet','sure','saat','dakika kaldı','rekât farz','gün'],ru:['аятов','сур','ч','мин осталось','ракаата фард','дней'],en:['verses','surahs','h','min left','fard rakats','days'],ar:['آيات','سور','س','د متبقية','ركعات فرض','أيام']}[lang()];return out.replace(/ayə/g,units[0]).replace(/surə/g,units[1]).replace(/saat/g,units[2]).replace(/dəqiqə qaldı/g,units[3]).replace(/rükət fərz/g,units[4]).replace(/dəfə/g,({tr:'kez',ru:'раз',en:'times',ar:'مرات'})[lang()]).replace(/\bgün\b/g,units[5])}
function localizeUI(){if(typeof document.createTreeWalker!=='function')return;document.documentElement.lang=lang();document.documentElement.dir=lang()==='ar'?'rtl':'ltr';const walk=document.createTreeWalker(document.body,4);let n;while(n=walk.nextNode()){if(n.parentElement?.closest('script,style,[data-localized],#onboarding,[lang="ar"]:not(html),.arabic,.translit,.brand-name'))continue;const v=n.nodeValue;if(v.trim()){const next=tr(v);if(next!==v)n.nodeValue=next}}for(const e of document.querySelectorAll('[placeholder],[aria-label]'))for(const a of ['placeholder','aria-label']){const v=e.getAttribute(a);if(v){const next=tr(v);if(next!==v)e.setAttribute(a,next)}}}
function setLanguage(code){if(!languageOptions.some(x=>x[0]===code))return;save('basira-language',code);quranQuery='';quranPage=0;render()}
function languagePage(){return head('Dil seçimi','')+`<section class="card language-list">${languageOptions.map(([code,name])=>`<button class="row" lang="${code}" dir="${code==='ar'?'rtl':'ltr'}" onclick="setLanguage('${code}')" aria-pressed="${lang()===code}"><span class="grow">${name}</span><span>${lang()===code?'✓':'○'}</span></button>`).join('')}</section>`}
function localizedDate(d){const l=lang();if(l==='az')return `${d.getDate()} ${['yanvar','fevral','mart','aprel','may','iyun','iyul','avqust','sentyabr','oktyabr','noyabr','dekabr'][d.getMonth()]} ${d.getFullYear()}`;return new Intl.DateTimeFormat(l,{day:'numeric',month:'long',year:'numeric'}).format(d)}
