function localizedMonth(d){return lang()==='az'?['Yanvar','Fevral','Mart','Aprel','May','İyun','İyul','Avqust','Sentyabr','Oktyabr','Noyabr','Dekabr'][d.getMonth()]+' '+d.getFullYear():new Intl.DateTimeFormat(lang(),{month:'long',year:'numeric'}).format(d)}
function shortDateLabel(d,monthOnly=false){if(lang()==='az'){const m=['yan','fev','mar','apr','may','iyn','iyl','avq','sen','okt','noy','dek'][d.getMonth()];return monthOnly?m:d.getDate()+' '+m}return new Intl.DateTimeFormat(lang(),monthOnly?{month:'short'}:{day:'numeric',month:'short'}).format(d)}
